targets.code:
{% comment %}
===================================================================
[CÁCH 1 - Khuyên dùng]: Phân biệt nút Buy Now vs Add to Cart
Tránh lỗi: Khách bấm Buy Now nhưng lại bị chuyển hướng vào giỏ hàng
===================================================================
{% endcomment %}
<script>
window._isBuyNowClicked = false;
function bindBuyNowButton(button) {
  if (!button || button.dataset.bound === 'true') return;
  button.dataset.bound = 'true';
  button.addEventListener('click', () => { window._isBuyNowClicked = true; });
}
function bindAtcButton(button) {
  if (!button || button.dataset.bound === 'true') return;
  button.dataset.bound = 'true';
  button.addEventListener('click', () => { window._isBuyNowClicked = false; });
}
function observePopupBuyNowButtons() {
  const observer = new MutationObserver(() => {
    const popupBuyNowBtn = document.querySelector('.tee-dialog .tee-btn--buynow');
    if (popupBuyNowBtn) bindBuyNowButton(popupBuyNowBtn);
    const popupAtcBtn = document.querySelector('.tee-dialog .tee-btn--atc');
    if (popupAtcBtn) bindAtcButton(popupAtcBtn);
  });
  observer.observe(document.body, { childList: true, subtree: true });
}

document.addEventListener('teeinblue-event-component-injected', () => {
  bindBuyNowButton(document.querySelector('#teeBuynowButton'));
  bindAtcButton(document.querySelector('#teeAtcButton'));
  observePopupBuyNowButtons();
});

document.addEventListener('teeinblue-event-after-cart-added', () => {
  if (window._isBuyNowClicked) {
    window._isBuyNowClicked = false;
    return;
  }
  {% if product and product.metafields.custom.cross_sell_product.value %}
    const crossSellHandle = "{{ product.metafields.custom.cross_sell_product.value.handle }}";
    const crossSellUrl = "{{ product.metafields.custom.cross_sell_product.value.url }}";
    fetch('/cart.js')
      .then(res => res.json())
      .then(cart => {
        const isProductInCart = cart.items.some(item => item.handle === crossSellHandle);
        if (!isProductInCart) {
          window.location.href = crossSellUrl;
        } else {
          console.log("The cross-sell product is already in the cart.");
        }
      });
  {% else %}
    setTimeout(() => {
      window.location.href = "{{ routes.cart_url }}";
    }, 200);
  {% endif %}
});
</script>

{% comment %}
[CÁCH 1 - Khuyên dùng]: Chèn trực tiếp thẻ link vào template cart (ví dụ sections/main-cart-items.liquid):
{% assign customizationUrl = item.properties._customization_image %}
{% if customizationUrl %}
  <div class="tee-cart-preview-link">
    Preview: <a href="{{ customizationUrl }}" target="_blank" rel="noopener">Xem thiết kế</a>
  </div>
{% endif %}
{% endcomment %}

<!-- [CÁCH 2]: Cấu hình qua biến teeinblue trong theme.liquid -->
<script type="text/javascript">
  teeinblue = {
    addCartPreviewButton: true,
    cartPreviewButtonText: 'Xem ảnh cá nhân hóa',
    cartContainerSelectors: ['.cart-item', '.cart__items'],
    cartItemWrapperSelectors: ['.product-cart-item', '.cart-item'],
    cartPreviewButtonWrapperSelectors: ['.product-cart-item > div:last-child', '.cart-item__details'],
    cartPreviewCheckoutLabel: 'Process to Checkout',
    cartPreviewShowCheckout: false,
  };
</script>

/* Style gạch chéo variant sold out */
.tee-radio.soldout {
  position: relative;
  opacity: 0.5;
}

.tee-radio.soldout:before {
  content: "";
  position: absolute;
  top: 50%;
  left: 0;
  right: 0;
  height: 1.5px;
  background-color: #ff0000;
  transform: rotate(-30deg);
  z-index: 2;
}

{% comment %} Cảnh báo thiếu customization_id trong giỏ hàng {% endcomment %}
{% for property in item.properties %}
  {% if property.first contains '_customization_id' and property.last != blank %}
    {% assign hasTibId = true %}
    {% break %}
  {% endif %}
{% endfor %}

{% if item.product.metafields.teeinblue.campaign_version and hasTibId != true %}
  <div class="teeinblue-warning-no-customization" style="color: #EC0101; border: 2px solid #EC0101; padding: 10px; margin-top: 8px; border-radius: 4px; font-weight: 500;">
    Lỗi: Chưa nhận diện được thiết kế cá nhân hóa. Vui lòng xóa mục này và thêm lại từ trang sản phẩm!
  </div>
{% endif %}

